def masaj(s):
    n, k = s["name"], s["kw"]
    parts = [
        s["intro"],
        f"## {n} Nedir?",
        s["what"],
        f"## Kimler İçin Uygundur?",
        ul(s["for"]),
        s.get("caution", ""),
        f"## Şırnak'ta {n} Nasıl Uygulanır?",
        ul(s["steps"]),
        "## Seans Öncesi ve Sonrası Öneriler",
        ul(s["tips"]),
        f"## {k}: Eve Gelen Masör ile Adresinizde",
        f"Doğal Dokunuş olarak salonumuz yok; seyyar çalışıyoruz. Randevu verdiğiniz saatte {ILCELER} başta olmak üzere Şırnak'ın tüm ilçelerinde evinize geliyoruz. Çalışma saatlerimiz 09:00–21:00 arasıdır. Randevu ve bilgi için arayabilir ya da WhatsApp'tan yazabilirsiniz.",
    ]
    return "\n\n".join(p for p in parts if p)

