def sql_lit(s): return "'" + s.replace("'", "''") + "'"

def build(site):
    rows = T if site == "tesisat" else M
    fn = tesisat if site == "tesisat" else masaj
    out = ["begin;"]
    for s in rows:
        faqs = json.dumps([{"q": q, "a": a} for q, a in s["faqs"]], ensure_ascii=False)
        out.append(f"update services set content={sql_lit(fn(s))}, faqs={sql_lit(faqs)}::jsonb where slug='{s['slug']}' and site_id=(select id from sites where slug='{site}');")
    out.append("commit;")
    return "\n".join(out)

if __name__ == "__main__":
    print(build(sys.argv[1]))
